1	// Kiểm tra chế độ đi dạo một mình trên máy tính (docs/superpowers/plans/2026-11-11-di-dao.md, Task 6).
2	//   Trang A `?test&explore=stroll`:
3	//   Mục 1: vào chế độ (cam.mode, lớp body, bảng tham quan ẩn, điểm xuất phát, cao độ lề Cầu Rồng).
4	//   Mục 2: cao độ chân khớp mặt cầu / mặt đất tại 12 điểm mẫu (tia thẳng xuống vào cảnh).
5	//   Mục 3: oracle độc lập với bản đồ: hơn 30 000 bước ngẫu nhiên (11 điểm xa nhà + 16 điểm sát tường nhà), mỗi 20 bước 8 tia ngang × 3 cao độ vào tam giác thật của các lưới rắn;
6	//          mỗi bước tâm nhân vật không nằm trong hộp bao nhà (theo hình học), đếm bước gần nhà (không rỗng), đẩy thẳng vào một bức tường để chứng minh tia thấy tường.
7	//   Mục 4: không ra ngoài mép kè trừ cầu / Cầu Tình Yêu, không thấp hơn mặt đất.
8	//   Mục 5: camera sát tường nhà không chui vào nhà, không xuống dưới mặt đất.
9	//   Mục 8: draw call của người đi dạo đúng 1.
10	//   Mục 7: cầu quay: sơ tán khỏi nhịp, không vào lại khi chưa đóng, đóng thì vào được.
11	//   Mục 6: phím W theo hướng camera, blur dừng (Review Focus 3), gõ trong ô nhập không điều khiển, Space một lần nhảy một lần, Esc thoát.
12	//   Trang B `?test`: không có `stroll-people` trong cảnh.
13	//   Mục 9 (Task 7): sảnh đi dạo qua màn chọn với máy chủ giả (routeWebSocket): chữ đi dạo, đổi ngôn ngữ ar / en đổi ngay, Quay lại → Dù lượn về chữ dù lượn,
14	//          máy chủ cũ (lobby không walkers) → ngoại tuyến, Đi một mình.
15	//   Mục 11 (Task 9): chụp ảnh: PNG đúng khung WebGL (tên, kích thước = canvas, 400 điểm mẫu), phím p, 5 lần bấm, đổi cỡ cửa sổ, bậc thấp, preserveDrawingBuffer = false.
16	//   Mục 10 (Task 7): cả 9 file locale có đủ khóa st* và exWalk / exWalkDesc.
17	//
18	//   npm run build && npm run test:stroll
19	//
20	//   Oracle mục 3 (không dùng bản đồ va chạm): tam giác thế giới của các lưới rắn, xếp vào lưới ô 2 m để chỉ thử tam giác gần nhân vật
21	//   (Raycaster trên cả cảnh với 24 000 tia không xong trong thời gian hợp lý trên SwiftShader). Thử tia bằng Ray.intersectTriangle
22	//   không loại mặt sau = vật liệu DoubleSide. Lưới dùng: nhà level gần của THREE.LOD (InstancedMesh, mọi instance còn hiện quanh khung đi dạo),
23	//   `dragon-body` (thân rồng), `dragon-head` (cả nhóm đầu rồng), `sh-tower` (tháp Cầu sông Hàn), `rf-landmarks` (địa danh ven sông, gồm cả
24	//   cầu tàu, lan can, hàng khóa và tượng cá chép Cầu Tình Yêu). Không dùng: cây, cột đèn, ghế, xe, người, dây văng, bảng quảng cáo (spec §4: đi xuyên được).
25	//   Cao độ tia tính từ cao độ đứng tại chỗ (không từ chân khi đang nhảy): spec chỉ chặn trong tầm người tính từ mặt đứng.
26	import { fileURLToPath } from 'node:url';
27	import { readFileSync } from 'node:fs';
28	import { serveDir, launch, openApp, frames } from './lib.mjs';
29	
30	const problems = [];
31	const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };
32	
33	/* Chạy trong trang: hàm dùng chung (đặt nhân vật, tìm vùng, tia thẳng xuống) */
34	function installHelpers() {
35	  const a = window.__app, S = a.stroll, T = a.THREE;
36	  const map = () => S.stroll.map;
37	  const zoneAt = (x, z) => {
38	    for (const zn of map().zones) {
39	      if (x < zn.x0 || x > zn.x1 || z < zn.z0 || z > zn.z1) continue;
40	      if (zn.gate !== undefined && map().closed.has(zn.gate)) continue;
41	      return zn;
42	    }
43	    return null;
44	  };
45	  const put = (x, z) => {
46	    const s = S.stroll.state, g = S.stGroundY(map(), x, z);
47	    s.x = x; s.z = z; s.y = g; s.vy = 0; s.air = false; s.evac = false; s.speed = 0; s.tx = x; s.tz = z; s.photo = 0;
48	    return g;
49	  };
50	  /* vật đi xuyên được (spec §4) hoặc không phải mặt rắn: bỏ qua khi tìm mặt đứng */
51	  const through = (o) => {
52	    if (o.isInstancedMesh || o.isPoints || o.isLine || o.isSprite || o.name === 'stroll-people') return true;
53	    for (let p = o; p; p = p.parent) if (!p.visible) return true;
54	    return false;
55	  };
56	  const rc = new T.Raycaster(); rc.layers.enableAll(); rc.camera = a.camera;
57	  const down = (x, y, z) => {
58	    rc.set(new T.Vector3(x, y + 3, z), new T.Vector3(0, -1, 0)); rc.near = 0; rc.far = 10;
59	    for (const h of rc.intersectObject(a.scene, true)) if (!through(h.object)) return { y: h.point.y, name: h.object.name || h.object.type, par: h.object.parent?.name || '' };
60	    return null;
61	  };
62	  window.__st = { zoneAt, put, down };
63	}
64	
65	const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
66	const browser = await launch();
67	try {
68	  const A = await openApp(browser, srv.url + '?explore=stroll');
69	  const P = A.page;
70	  await frames(P, 3);
71	  const has = await P.evaluate(() => !!(window.__app && window.__app.stroll && window.__app.stroll.stroll));
72	  check('có __app.stroll', has);
73	  if (!has) throw new Error('chưa có chế độ đi dạo (__app.stroll)');
74	  await P.evaluate(installHelpers);
75	
76	  // Mục 1 — vào chế độ
77	  {
78	    const r = await P.evaluate(() => {
79	      const a = window.__app, S = a.stroll, s = S.stroll.state, C = S.CONFIG_stroll;
80	      const vis = (sel) => { a.ui?.reveal(document.querySelector(sel)); const e = document.querySelector(sel); return !!e && e.getClientRects().length > 0 && getComputedStyle(e).visibility !== 'hidden'; };
81	      const hidden = ['[data-bridge="dragon"]', '[data-view="tour"]', '[data-view="allTour"]', '#tourCaption', '.specs', 'h1'].filter((q) => vis(q));
82	      a.ui?.closeSheets();   // reveal mở tờ điều khiển; tờ còn mở thì Esc đầu chỉ đóng tờ (compactUI)
83	      const d = window.__st.down(s.x, s.y, s.z);
84	      return { mode: a.cam.mode, ctl: a.controls.enabled, ex: document.body.classList.contains('explore'), st: document.body.classList.contains('stroll'), act: S.stroll.active(),
85	        leaked: hidden, x: s.x, z: s.z, y: s.y, sx: C.spawn.x, sz: C.spawn.z, hit: d, obj: !!a.scene.getObjectByName('stroll-people') };
86	    });
87	    check(`1 cam.mode ${r.mode}, controls ${r.ctl}, body.explore ${r.ex}, body.stroll ${r.st}, active ${r.act}, scene có stroll-people ${r.obj}`, r.mode === 'stroll' && r.ctl === false && r.ex && r.st && r.act && r.obj);
88	    check(`1 bảng tham quan ẩn (lọt: ${r.leaked.join(',') || '-'})`, r.leaked.length === 0);
89	    check(`1 xuất phát slot −1 tại (${r.x.toFixed(2)}, ${r.z.toFixed(2)}) = spawn (${r.sx}, ${r.sz})`, Math.abs(r.x - r.sx) < 1e-6 && Math.abs(r.z - r.sz) < 1e-6);
90	    check(`1 y ${r.y.toFixed(3)} = mặt lề Cầu Rồng ${r.hit ? r.hit.y.toFixed(3) + ' (' + r.hit.name + ')' : '-'} ± 0,02`, !!r.hit && Math.abs(r.y - r.hit.y) <= 0.02);
91	  }
92	
93	  // Mục 2 — cao độ tại 12 điểm mẫu
94	  {
95	    const r = await P.evaluate(() => {
96	      const S = window.__app.stroll, SHZ = -1080;
97	      const pts = [
98	        ['Cầu Rồng lề Nam', -240, 17.4], ['Cầu Rồng lề Bắc', 150, -17.6], ['Cầu Rồng lòng đường gần đầu Tây', -300, 9], ['Cầu Rồng đường dẫn Đông (vỉa hè)', 345, 18.2],
99	        ['Cầu sông Hàn lề Nam phần cố định', -150, SHZ + 5.5], ['Cầu sông Hàn lề Bắc nhịp quay', 40, SHZ - 5.5], ['Cầu sông Hàn lòng đường', 200, SHZ + 3], ['Cầu sông Hàn đường dẫn Đông', 300, SHZ + 2.5],
100	        ['bờ Tây lối dạo', -275, -500], ['bờ Đông lối dạo', 275, -600], ['bờ Tây đường Bạch Đằng', -305, -300], ['Cầu Tình Yêu', 240, -78]
101	      ];
102	      return pts.map(([n, x, z]) => {
103	        const ok = S.stValid(S.stroll.map, x, z, 0), y = window.__st.put(x, z), d = window.__st.down(x, y, z);
104	        return { n, x, z, ok, y, hit: d };
105	      });
106	    });
107	    for (const p of r) check(`2 ${p.n} (${p.x}, ${p.z}): hợp lệ ${p.ok}, chân ${p.y.toFixed(3)}, mặt trúng ${p.hit ? p.hit.y.toFixed(3) + ' ' + p.hit.name + (p.hit.par ? '<' + p.hit.par : '') : '-'} (≤ 0,15)`,
108	      p.ok && !!p.hit && Math.abs(p.y - p.hit.y) <= 0.15);
109	  }
110	
111	  // Mục 3 + 4 — 20 000 bước ngẫu nhiên, oracle bằng tam giác thật của lưới rắn
112	  {
113	    const r = await P.evaluate(() => {
114	      const a = window.__app, S = a.stroll, T = a.THREE, C = S.CONFIG_stroll, map = S.stroll.map, B = C.bounds, R = C.radius;
115	      const Ray = new T.Raycaster().ray.constructor;
116	      /* --- gom tam giác thế giới của các lưới rắn vào lưới ô 2 m --- */
117	      const CELL = 2, cells = new Map(), tri = [];
118	      const key = (ix, iz) => ix * 100003 + iz;
119	      const v = [new T.Vector3(), new T.Vector3(), new T.Vector3()], mw = new T.Matrix4(), mi = new T.Matrix4(), p = new T.Vector3(), q = new T.Quaternion(), sc = new T.Vector3();
120	      const boxes = [];   // hộp bao thế giới của từng nhà (cho mục 5)
121	      const counts = {};
122	      const addGeo = (geo, m, tag, box) => {
123	        const pos = geo.attributes.position, idx = geo.index, n = idx ? idx.count : pos.count;
124	        for (let i = 0; i + 2 < n; i += 3) {
125	          for (let k = 0; k < 3; k++) v[k].fromBufferAttribute(pos, idx ? idx.getX(i + k) : i + k).applyMatrix4(m);
126	          const x0 = Math.min(v[0].x, v[1].x, v[2].x), x1 = Math.max(v[0].x, v[1].x, v[2].x), z0 = Math.min(v[0].z, v[1].z, v[2].z), z1 = Math.max(v[0].z, v[1].z, v[2].z);
127	          if (box) { box.x0 = Math.min(box.x0, x0); box.x1 = Math.max(box.x1, x1); box.z0 = Math.min(box.z0, z0); box.z1 = Math.max(box.z1, z1); }
128	          if (x1 < B.x0 - 5 || x0 > B.x1 + 5 || z1 < B.z0 - 5 || z0 > B.z1 + 5) continue;
129	          const t = tri.length; tri.push([v[0].clone(), v[1].clone(), v[2].clone(), tag]);
130	          for (let ix = Math.floor(x0 / CELL); ix <= Math.floor(x1 / CELL); ix++) for (let iz = Math.floor(z0 / CELL); iz <= Math.floor(z1 / CELL); iz++) {
131	            const k = key(ix, iz); let l = cells.get(k); if (!l) { l = []; cells.set(k, l); } l.push(t);
132	          }
133	          counts[tag] = (counts[tag] || 0) + 1;
134	        }
135	      };
136	      const addObj = (root, tag) => {
137	        root.updateMatrixWorld(true);
138	        root.traverse((o) => {
139	          if (!o.isMesh) return;
140	          if (o.isInstancedMesh) { for (let i = 0; i < o.count; i++) { o.getMatrixAt(i, mi); mi.decompose(p, q, sc); if (sc.x < 1e-6) continue; addGeo(o.geometry, mw.multiplyMatrices(o.matrixWorld, mi), tag); } }
141	          else addGeo(o.geometry, o.matrixWorld, tag);
142	        });
143	      };
144	      a.scene.updateMatrixWorld(true);
145	      /* nhà: InstancedMesh level gần của THREE.LOD (như collectBuildings) */
146	      a.scene.traverse((o) => {
147	        if (!o.isInstancedMesh || !o.parent || !o.parent.isLOD || o.parent.levels[0]?.object !== o) return;
148	        for (let i = 0; i < o.count; i++) {
149	          o.getMatrixAt(i, mi); mi.decompose(p, q, sc); if (sc.x < 1e-6) continue;
150	          mw.multiplyMatrices(o.matrixWorld, mi); p.set(0, 0, 0).applyMatrix4(mw);
151	          if (p.x < B.x0 - 60 || p.x > B.x1 + 60 || p.z < B.z0 - 60 || p.z > B.z1 + 60) continue;
152	          const box = { x0: Infinity, x1: -Infinity, z0: Infinity, z1: -Infinity }; addGeo(o.geometry, mw, 'nhà', box); boxes.push(box);
153	        }
154	      });
155	      const named = {};
156	      for (const n of ['dragon-body', 'dragon-head', 'sh-tower', 'rf-landmarks']) { const o = a.scene.getObjectByName(n); named[n] = !!o; if (o) addObj(o, n); }
157	      /* --- 24 tia ngang dài R quanh (x, z) ở 3 cao độ trên mặt đứng --- */
158	      const ray = new Ray(), tgt = new T.Vector3(), seen = new Set();
159	      const DIRS = Array.from({ length: 8 }, (_, i) => [Math.cos(i * Math.PI / 4), Math.sin(i * Math.PI / 4)]);
160	      const gather = (x, z, L) => {
161	        seen.clear();
162	        for (let ix = Math.floor((x - L) / CELL); ix <= Math.floor((x + L) / CELL); ix++) for (let iz = Math.floor((z - L) / CELL); iz <= Math.floor((z + L) / CELL); iz++) {
163	          const l = cells.get(key(ix, iz)); if (l) for (const t of l) seen.add(t);
164	        }
165	      };
166	      const probe = (x, g, z) => {
167	        gather(x, z, R); const hits = [];
168	        if (!seen.size) return hits;
169	        for (const dh of [0.3, 1.0, 1.7]) for (const [dx, dz] of DIRS) {
170	          ray.origin.set(x, g + dh, z); ray.direction.set(dx, 0, dz);
171	          for (const t of seen) {
172	            const h = tri[t], hp = ray.intersectTriangle(h[0], h[1], h[2], false, tgt);
173	            if (hp && hp.distanceTo(ray.origin) <= R) { hits.push({ tag: h[3], dh, d: +hp.distanceTo(ray.origin).toFixed(4) }); break; }
174	          }
175	        }
176	        return hits;
177	      };
178	      /* một tia ngang dài len từ (x, y, z) theo (dx, dz): khoảng cách tới tam giác gần nhất, hoặc null */
179	      const castH = (x, y, z, dx, dz, len) => {
180	        gather(x, z, len); let best = null;
181	        ray.origin.set(x, y, z); ray.direction.set(dx, 0, dz);
182	        for (const t of seen) {
183	          const h = tri[t], hp = ray.intersectTriangle(h[0], h[1], h[2], false, tgt);
184	          if (hp) { const d = hp.distanceTo(ray.origin); if (d <= len && (best === null || d < best)) best = d; }
185	        }
186	        return best;
187	      };
188	      /* khoảng cách mặt bằng từ (x, z) tới hộp nhà (0 nếu ở trong); trong hộp (đã thu 1 cm) = nhân vật nằm trong khối nhà */
189	      const EPS = 0.01;
190	      const boxDist = (b, x, z) => Math.hypot(Math.max(b.x0 - x, 0, x - b.x1), Math.max(b.z0 - z, 0, z - b.z1));
191	      const inBox = (b, x, z) => x > b.x0 + EPS && x < b.x1 - EPS && z > b.z0 + EPS && z < b.z1 - EPS;
192	      window.__st.boxes = boxes;   // mục 5 dùng lại hộp theo hình học
193	      /* --- 10 điểm xuất phát, 2 000 bước mỗi điểm --- */
194	      let seed = 20261111;
195	      const rnd = () => { seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
196	      const starts = [[-240, 17.4], [0, -10], [-300, 60], [-320, -500], [-320, -1150], [-150, -1074.5], [30, -1083], [320, -1150], [240, -78], [340, -660], [150, -1074.5]];
197	      const badStart = [], fails = [], out4 = [], inp = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };
198	      const BRIDGE = new Set(['shSwing', 'songHanW', 'songHanE', 'dragon', 'love']);
199	      let samples = 0, steps = 0, minY = Infinity, zonesSeen = new Set();
200	      /* chứng minh oracle không rỗng: mỗi BƯỚC kiểm tâm nhân vật không nằm trong khối nhà, đo khoảng cách tới nhà gần nhất, đếm bước đứng im khi đang đẩy */
201	      const inside = [], frozen = [];
202	      let near = 0, touch = 0, minBoxD = Infinity, still = 0, px = 0, pz = 0, frozenN = 0;
203	      const s = S.stroll.state;
204	      /* điểm xuất phát sát nhà: các nhà đi tới được lấy cách đều trong danh sách, đặt cách mặt tường 1,5 m, 1 000 bước mỗi điểm (đi ngẫu nhiên quanh nhà) */
205	      const startsN = starts.map(([x, z]) => [x, z, 2000]);
206	      let nearStarts = 0;
207	      for (let bi = 0; bi < boxes.length && nearStarts < 16; bi++) {
208	        const b = boxes[bi], mx = (b.x0 + b.x1) / 2, mz = (b.z0 + b.z1) / 2;
209	        for (const [x, z] of [[b.x1 + 1.5, mz], [b.x0 - 1.5, mz], [mx, b.z1 + 1.5], [mx, b.z0 - 1.5]]) {
210	          if (S.stValid(map, x, z, 0)) { startsN.push([x, z, 1000]); nearStarts++; break; }
211	        }
212	      }
213	      let expectSteps = 0;
214	      for (const [sx, sz, n] of startsN) {
215	        if (!S.stValid(map, sx, sz, 0)) { badStart.push(`${sx},${sz}`); continue; }
216	        expectSteps += n;
217	        window.__st.put(sx, sz);
218	        let left = 0; still = 0; px = s.x; pz = s.z;
219	        for (let i = 0; i < n; i++) {
220	          inp.jump = false;
221	          if (left-- <= 0) {
222	            left = 10 + Math.floor(rnd() * 50);
223	            inp.mx = rnd() < 0.3 ? 0 : rnd() * 2 - 1; inp.mz = rnd() < 0.2 ? 0 : rnd() * 2 - 1; inp.run = rnd() < 0.5; inp.jump = rnd() < 0.4; inp.camYaw = rnd() * Math.PI * 2;
224	            still = 0;
225	          }
226	          const dt = rnd() < 0.05 ? 0.1 : 1 / 30;
227	          S.stroll.step(dt, inp); steps++;
228	          if (s.y < minY) minY = s.y;
229	          let dMin = Infinity;
230	          for (const b of boxes) {
231	            if (inBox(b, s.x, s.z)) { if (inside.length < 8) inside.push({ x: +s.x.toFixed(3), z: +s.z.toFixed(3), step: steps, box: [b.x0, b.x1, b.z0, b.z1].map((n) => +n.toFixed(2)) }); }
232	            const d = boxDist(b, s.x, s.z); if (d < dMin) dMin = d;
233	          }
234	          if (dMin < minBoxD) minBoxD = dMin;
235	          if (dMin <= 1.5) near++;
236	          if (dMin <= R + 0.05) touch++;
237	          /* đứng im ≥ 30 bước liền trong một đoạn đầu vào đang đẩy */
238	          if (Math.hypot(inp.mx, inp.mz) > 0.3 && Math.hypot(s.x - px, s.z - pz) < 1e-5) { if (++still === 30) { frozenN++; if (frozen.length < 6) frozen.push({ x: +s.x.toFixed(2), z: +s.z.toFixed(2), boxD: +dMin.toFixed(2) }); } } else still = 0;
239	          px = s.x; pz = s.z;
240	          if (i % 20 === 19) {
241	            samples++;
242	            const g = S.stGroundY(map, s.x, s.z), zn = window.__st.zoneAt(s.x, s.z);
