463	    const NAME = /^danang-\d{8}-\d{6}\.png$/;
464	    /* mở file trong trang: kích thước, số màu khác nhau trong 400 điểm mẫu, có phải toàn đen không */
465	    const analyse = async (d) => {
466	      const buf = readFileSync(await d.path());
467	      const r = await Q.evaluate(async (b64) => {
468	        const bin = atob(b64), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
469	        const bmp = await createImageBitmap(new Blob([u], { type: 'image/png' }));
470	        const c = document.createElement('canvas'); c.width = bmp.width; c.height = bmp.height;
471	        const g = c.getContext('2d'); g.drawImage(bmp, 0, 0);
472	        const cols = new Set(); let lit = 0;
473	        for (let iy = 0; iy < 20; iy++) for (let ix = 0; ix < 20; ix++) {
474	          const px = g.getImageData(Math.min(bmp.width - 1, Math.floor((ix + 0.5) * bmp.width / 20)), Math.min(bmp.height - 1, Math.floor((iy + 0.5) * bmp.height / 20)), 1, 1).data;
475	          cols.add(px[0] + ',' + px[1] + ',' + px[2]); if (px[0] + px[1] + px[2] > 12) lit++;
476	        }
477	        return { w: bmp.width, h: bmp.height, colors: cols.size, lit };
478	      }, buf.toString('base64'));
479	      return { name: d.suggestedFilename(), ...r };
480	    };
481	    const waitCount = async (n) => { const t0 = Date.now(); while (got.length < n && Date.now() - t0 < 240000) await Q.waitForTimeout(200); };
482	    const valid = (a) => NAME.test(a.name) && a.colors >= 20 && a.lit > 0;
483	    const cv = () => Q.evaluate(() => { const c = document.querySelector('canvas'); return { w: c.width, h: c.height }; });
484	    // bấm #stPhoto: đúng 1 file
485	    await Q.click('#stPhoto');
486	    await waitCount(1);
487	    const toast = await Q.evaluate(() => { const e = document.getElementById('stToast'); return { hidden: e.hidden, text: e.textContent, shown: e.getClientRects().length > 0 }; });   // ô riêng #stToast; đọc ngay: thông báo tự ẩn sau noticeMs (8 s), SwiftShader chậm
488	    await frames(Q, 4);
489	    const a1 = await analyse(got[0]), c1 = await cv();
490	    check(`11 bấm #stPhoto: ${got.length} file (= 1) "${a1.name}", ${a1.w}×${a1.h} = canvas ${c1.w}×${c1.h}, ${a1.colors} màu / 400 điểm, sáng ${a1.lit}`, got.length === 1 && valid(a1) && a1.w === c1.w && a1.h === c1.h);
491	    const last = await Q.evaluate(() => window.__app.stroll.stroll.photoLast);
492	    check(`11 thông báo "${toast.text}" (stPhotoSaved) ở #stToast, đang hiện`, !toast.hidden && toast.shown && toast.text === 'Đã lưu ảnh');
493	    // thông báo nhiều người đang hiện ở #exMpNotice: chụp ảnh không được đè lên
494	    await Q.evaluate(() => { const n = document.getElementById('exMpNotice'); n.textContent = 'MP-NOTICE-GIU-NGUYEN'; n.hidden = false; });
495	    const nA = got.length;
496	    await Q.evaluate(() => document.getElementById('stPhoto').click());
497	    await waitCount(nA + 1);
498	    const both = await Q.evaluate(() => ({ mp: document.getElementById('exMpNotice').textContent, mpHidden: document.getElementById('exMpNotice').hidden, st: document.getElementById('stToast').textContent, stHidden: document.getElementById('stToast').hidden }));
499	    check(`11 chụp khi #exMpNotice đang có chữ: giữ "${both.mp}", #stToast "${both.st}" (stPhotoSaved)`, both.mp === 'MP-NOTICE-GIU-NGUYEN' && !both.mpHidden && !both.stHidden && both.st === 'Đã lưu ảnh');
500	    await Q.evaluate(() => { const n = document.getElementById('exMpNotice'); n.textContent = ''; n.hidden = true; });
501	    await frames(Q, 4);
502	    got.splice(nA);   // file thêm này chỉ để kiểm thông báo; các mục sau đếm lại từ đây
503	    check(`11 photoLast ${JSON.stringify(last)} khớp file`, !!last && last.name === a1.name && last.w === a1.w && last.h === a1.h && last.size > 1000);
504	    // phím p: thêm đúng 1 file; pose 4 khi đứng yên rồi về 0
505	    await Q.evaluate(() => document.activeElement && document.activeElement.blur());
506	    await Q.keyboard.press('p');
507	    const pose = await Q.evaluate(() => {
508	      const S = window.__app.stroll.stroll, idle = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 }, hold = window.__app.stroll.CONFIG_stroll.photoHold;
509	      S.step(0.016, idle); const p0 = S.state.pose;
510	      let t = 0, p1 = p0; while (t < hold - 0.1) { S.step(0.05, idle); t += 0.05; p1 = S.state.pose; }
511	      for (let i = 0; i < 6; i++) S.step(0.05, idle);
512	      return { p0, p1, end: S.state.pose };
513	    });
514	    check(`11 phím p: pose ${pose.p0} → ${pose.p1} trong photoHold (= 4) → ${pose.end} (= 0)`, pose.p0 === 4 && pose.p1 === 4 && pose.end === 0);
515	    await waitCount(2); await frames(Q, 4);
516	    check(`11 phím p: thêm đúng 1 file (tổng ${got.length} = 2), tên hợp lệ`, got.length === 2 && NAME.test(got[1].suggestedFilename()));
517	    // 5 lần bấm trong một khung
518	    const n0 = got.length;
519	    await Q.evaluate(() => { const b = document.getElementById('stPhoto'); for (let i = 0; i < 5; i++) b.click(); });
520	    await waitCount(n0 + 1); await frames(Q, 6);
521	    const many = got.slice(n0), am = [];
522	    for (const d of many) am.push(await analyse(d));
523	    check(`11 bấm 5 lần trong một khung: ${many.length} file (1..5), mỗi file hợp lệ (${am.map((a) => a.colors).join(',')} màu)`, many.length >= 1 && many.length <= 5 && am.every(valid));
524	    // đổi kích thước rồi bấm ngay: kích thước file = canvas lúc chụp
525	    const n1 = got.length;
526	    await Q.setViewportSize({ width: 560, height: 315 });
527	    await Q.evaluate(() => document.getElementById('stPhoto').click());
528	    await waitCount(n1 + 1); await frames(Q, 6);
