530	    check(`11 đổi cỡ cửa sổ rồi bấm ngay: file ${ar.w}×${ar.h} = canvas lúc chụp ${lr.w}×${lr.h}, ${got.length - n1} file (= 1)`, got.length === n1 + 1 && valid(ar) && ar.w === lr.w && ar.h === lr.h);
531	    // bậc chất lượng thấp nhất
