534	    await frames(Q, 4);
535	    await Q.evaluate(() => document.getElementById('stPhoto').click());
536	    await waitCount(n2 + 1); await frames(Q, 4);
537	    const aq = await analyse(got[n2]);
538	    check(`11 chất lượng thấp: ${got.length - n2} file (= 1), ${aq.w}×${aq.h}, ${aq.colors} màu, hợp lệ`, got.length === n2 + 1 && valid(aq));
539	    check('console sạch (chụp ảnh)', C.errors.length === 0);
540	    if (C.errors.length) console.log(C.errors.join('\n'));
541	    await Q.close();
542	  }
543	
544	  // Mục 9 (Task 7) — sảnh đi dạo đổi ngôn ngữ; máy chủ giả bằng routeWebSocket (không cần wrangler): gửi lobby có walkers, rồi bản máy chủ cũ (không walkers)
545	  {
546	    const L = await browser.newPage({ viewport: { width: 480, height: 270 } });
547	    const errs = []; L.on('pageerror', (e) => errs.push(String(e)));
548	    L.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|ERR_FAILED|net::/.test(m.text())) errs.push(m.text()); });
549	    await L.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
550	    let oldServer = false, opened = 0;
551	    await L.routeWebSocket(/127\.0\.0\.1:1\/sky/, (ws) => { opened++; ws.send(JSON.stringify(oldServer ? { t: 'lobby', flyers: [{ slot: 0, name: 'Bay' }] } : { t: 'lobby', flyers: [{ slot: 0, name: 'Bay' }], walkers: [] })); });
552	    await L.addInitScript(() => { try { sessionStorage.setItem('exMpNotice', 'lostWalk'); } catch { /* bỏ qua */ } });   // như vừa mất kết nối khi xem người đi dạo
553	    await L.goto(srv.url + '?test&chooser&multi=' + encodeURIComponent('ws://127.0.0.1:1/sky'), { waitUntil: 'load', timeout: 180000 });
554	    await L.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
555	    await L.waitForSelector('#chooser', { state: 'visible', timeout: 240000 });
556	    const loc = (c) => JSON.parse(readFileSync(new URL(`../src/i18n/locales/${c}.json`, import.meta.url), 'utf8'));
557	    {
558	      const note = () => L.evaluate(() => { const n = document.getElementById('exMpLostNote'); return { txt: n.innerText, shown: n.getClientRects().length > 0, flag: sessionStorage.getItem('exMpNotice') }; });
559	      const n0 = await note();
560	      check(`9 mất kết nối khi xem người đi dạo: màn chọn hiện "${n0.txt}" (stLostChooser vi, nhắc Đi dạo), cờ đã xóa (${n0.flag})`, n0.shown && n0.txt === loc('vi').stLostChooser && /Đi dạo/.test(n0.txt) && n0.flag === null);
561	      await L.selectOption('#exLang', 'en');
562	      const n1 = await note();
563	      check(`9 đổi sang en: "${n1.txt}" (stLostChooser en)`, n1.txt === loc('en').stLostChooser);
564	      await L.selectOption('#exLang', 'vi');
565	    }
566	    const lobbyTxt = () => L.evaluate(() => ({ sky: document.getElementById('exMpSky').innerText, seats: document.getElementById('exMpSeats').innerText, go: document.getElementById('exMpFly').innerText, solo: document.getElementById('exMpSolo').innerText, dir: document.documentElement.dir, list: document.getElementById('exMpList').children.length, kind: window.__app.multi.session && window.__app.multi.session.kind }));
567	    await L.click('#chooser [data-pick="walk"]');
568	    await L.waitForFunction(() => /Còn 5 trên 5 chỗ đi dạo/.test(document.getElementById('exMpSeats')?.innerText || ''), null, { timeout: 30000 }).catch(() => {});
569	    const v0 = await lobbyTxt(), V = loc('vi');
570	    check(`9 bấm thẻ Đi dạo: sảnh "${v0.sky}", "${v0.seats}", nút "${v0.go}", không liệt kê người bay (${v0.list}), phiên ${v0.kind}`, v0.kind === 'walk' && v0.seats === 'Còn 5 trên 5 chỗ đi dạo' && v0.sky === V.stSky && v0.go === V.stGo && v0.solo === V.stSolo && v0.list === 0);
571	    for (const c of ['ar', 'en']) {
572	      await L.selectOption('#exLang', c);
573	      const r = await lobbyTxt(), T = loc(c);
574	      check(`9 đổi sang ${c}: "${r.seats}", nút "${r.go}", tiêu đề "${r.sky}", dir ${r.dir}`, r.seats === T.stSeats.replace('{n}', '5') && r.go === T.stGo && r.sky === T.stSky && r.dir === (c === 'ar' ? 'rtl' : 'ltr'));
575	    }
576	    await L.selectOption('#exLang', 'vi');
577	    // Quay lại rồi chọn Dù lượn: chữ sảnh trở về của dù lượn
578	    await L.click('#exMpBack');
579	    await L.click('#chooser [data-pick="glider"]');
580	    await L.waitForFunction(() => /Còn 4 trên 5 chỗ$/.test(document.getElementById('exMpSeats')?.innerText || ''), null, { timeout: 30000 }).catch(() => {});
581	    const g = await lobbyTxt();
582	    check(`9 Quay lại rồi chọn Dù lượn: "${g.sky}", "${g.seats}", nút "${g.go}"`, g.kind === 'fly' && g.sky === V.exMpSky && g.go === V.exMpFly && g.seats === V.exMpSeats.replace('{n}', '4'));
583	    // Máy chủ cũ (lobby không có walkers): đi dạo coi là ngoại tuyến, đóng kết nối, nút Đi một mình
584	    await L.click('#exMpBack');
585	    oldServer = true;
586	    await L.click('#chooser [data-pick="walk"]');
587	    await L.waitForFunction(() => !document.getElementById('exMpOffline').hidden, null, { timeout: 30000 }).catch(() => {});
588	    const o = await L.evaluate(() => ({ off: document.getElementById('exMpOffline').innerText, solo: document.getElementById('exMpSolo').innerText, phase: window.__app.multi.session && window.__app.multi.session.phase }));
589	    check(`9 máy chủ cũ: "${o.off}", nút "${o.solo}", phase ${o.phase}, ${opened} kết nối giả`, o.off === V.stOffline && o.solo === V.stSolo && o.phase === 'solo' && opened === 3);
590	    await L.click('#exMpSolo');
591	    await L.waitForFunction(() => window.__app.stroll.stroll.active(), null, { timeout: 60000 }).catch(() => {});
592	    const so = await L.evaluate(() => ({ act: window.__app.stroll.stroll.active(), hidden: document.getElementById('chooser').hidden, session: window.__app.multi.session }));
593	    check('9 bấm Đi một mình: đi dạo một mình, hộp đóng, không còn phiên', so.act && so.hidden && so.session === null);
594	    check('console sạch (sảnh đi dạo)', errs.length === 0);
595	    if (errs.length) console.log(errs.join('\n'));
596	    await L.close();
597	  }
598	
599	  // Mục 10 (Task 7) — cả 9 file locale có đủ mọi khóa st* và exWalkDesc (không rỗng)
600	  {
601	    const codes = ['vi', 'en', 'ko', 'ja', 'zh', 'th', 'ar', 'hi', 'ru'];
602	    const all = Object.fromEntries(codes.map((c) => [c, JSON.parse(readFileSync(new URL(`../src/i18n/locales/${c}.json`, import.meta.url), 'utf8'))]));
603	    const need = ['stSky', 'stSeats', 'stFull', 'stGo', 'stSolo', 'stOffline', 'stRoster', 'stWatch', 'stInvite', 'stInviteGo', 'stLate', 'stReleased', 'stLost', 'stJump', 'stPhoto', 'stPhotoSaved', 'stPhotoFail'];
604	    const keys = [...new Set([...need, ...codes.flatMap((c) => Object.keys(all[c]).filter((k) => /^st[A-Z]/.test(k))), 'exWalk', 'exWalkDesc'])];
605	    const miss = [];
606	    for (const c of codes) for (const k of keys) if (typeof all[c][k] !== 'string' || !all[c][k].trim()) miss.push(`${c}.${k}`);
607	    const params = codes.filter((c) => !all[c].stSeats.includes('{n}') || !all[c].stRoster.includes('{w}') || !all[c].stRoster.includes('{f}') || !all[c].stWatch.includes('{name}'));
608	    check(`10 9 locale có đủ ${keys.length} khóa st* + exWalk/exWalkDesc (thiếu: ${miss.join(',') || '-'}), tham số đủ (lỗi: ${params.join(',') || '-'}), exWalk vi "${all.vi.exWalk}"`, miss.length === 0 && params.length === 0 && all.vi.exWalk === 'Đi dạo' && all.ar._dir === 'rtl');
609	  }
610	} catch (e) {
611	  problems.push('ngoại lệ: ' + e); console.log(e);
612	} finally {
613	  await browser.close(); srv.close();
614	}
615	console.log(problems.length ? `stroll-check: LỖI (${problems.length}): ${problems.join('; ')}` : 'stroll-check: đạt');
616	process.exit(problems.length ? 1 : 0);
