500	  await H.page.evaluate(() => {
501	    const raf = window.requestAnimationFrame.bind(window); window.__raf = raf; window.__held = [];
502	    window.requestAnimationFrame = (cb) => { window.__held.push(cb); return 0; };
503	    Object.defineProperty(document, 'hidden', { configurable: true, get: () => true });
504	    Object.defineProperty(document, 'visibilityState', { configurable: true, get: () => 'hidden' });
505	    document.dispatchEvent(new Event('visibilitychange'));
506	  });
507	  await sleep(23000);
508	  const keptHidden = obs.n === 1;
509	  const phaseHidden = await H.page.evaluate(() => window.__app.multi.session.phase);
510	  await H.page.evaluate(() => {
511	    delete document.hidden; delete document.visibilityState;
512	    document.dispatchEvent(new Event('visibilitychange'));
513	    window.requestAnimationFrame = window.__raf; const h = window.__held.splice(0); h.forEach((cb) => window.__raf(cb));
514	  });
515	  await frames(H.page, 20);
516	  const back = await H.page.evaluate(() => ({ phase: window.__app.multi.session.phase, active: window.__app.explore.active() }));
517	  check(`Tab ẩn và rAF dừng 23 s: slot còn (lobby ${obs.n}, phase ${phaseHidden}); quay lại vẫn bay, console không lỗi`, keptHidden && phaseHidden === 'flying' && back.phase === 'flying' && back.active && H.errors.length === 0);
518	  if (H.errors.length) console.log(H.errors.join('\n'));
519	  await H.page.close();
520	  try { ows.close(); } catch { /* bỏ qua */ }
521	  await sleep(2000);
522	
523	  // Mục 6 (Task 7, đi dạo) — người đi dạo và người bay thấy nhau, sảnh đi dạo, chế độ xem, lời mời, ô tên, khách cũ, rời máy
524	  const URLC = srv.url + '?chooser&multi=' + encodeURIComponent(`ws://${HOST}/sky`);
525	  const RUN_AMP = 0.6;   // CONFIG.people.run.amp: biên độ hông khi chạy (rad)
526	  const peopleOn = (pg) => pg.evaluate(() => { const m = window.__app.scene.getObjectByName('stroll-people'); if (!m) return { has: false, n: 0, vis: false }; const M = new window.__app.THREE.Matrix4(); let n = 0; for (let i = 0; i < m.count; i++) { m.getMatrixAt(i, M); if (Math.abs(M.determinant()) > 1e-9) n++; } return { has: true, n, vis: m.visible }; });
527	  const walkCard = async (pg) => { await pg.waitForSelector('#chooser', { state: 'visible', timeout: 240000 }); await pg.click('#chooser [data-pick="walk"]'); };
528	  const walkTo = async (pg, name) => {   // sảnh đi dạo → nhập tên → Đi dạo ngay → đang đi với slot
529	    await pg.waitForFunction(() => /Còn \d trên 5 chỗ đi dạo/.test(document.getElementById('exMpSeats')?.innerText || ''), null, { timeout: 30000 }).catch(() => {});
530	    await pg.fill('#exMpNameIn', name);
531	    await pg.click('#exMpFly');
532	    await pg.waitForFunction(() => window.__app.stroll.stroll.active() && window.__app.multi.session.phase === 'flying', null, { timeout: 60000 }).catch(() => {});
533	  };
534	  /* Bot đi dạo: join kind 'walk', đứng tại (x, y, z) gửi pose 5 lần/s; b.slot = slot được cấp */
535	  function walkBot(name, x, y, z, pose) {
536	    const ws = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: 'http://127.0.0.1' } });
537	    const b = { ws, timer: null, name, slot: -1 };
538	    ws.onopen = () => ws.send(JSON.stringify({ t: 'join', name, kind: 'walk' }));
539	    ws.onmessage = (e) => {
540	      const m = JSON.parse(e.data);
541	      if (m.t === 'joined' && !b.timer) { b.slot = m.slot; b.timer = setInterval(() => ws.send(JSON.stringify({ t: 'pos', x, y, z, yaw: 0, pose, ts: Date.now() })), 200); }
542	    };
543	    b.close = () => { clearInterval(b.timer); try { ws.close(); } catch { /* bỏ qua */ } };
544	    wbots.push(b);
545	    return b;
546	  }
547	  const dropW = (b) => { b.close(); const i = wbots.indexOf(b); if (i >= 0) wbots.splice(i, 1); };
548	
549	  // 6d — bot giả khách cũ (join không kind, chỉ đọc flyers / f) cùng phòng với 2 bot đi dạo (Review Focus 4)
550	  {
551	    const oldMsgs = [];
552	    const ows2 = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: 'http://127.0.0.1' } });
553	    let oldTimer = null;
554	    ows2.onopen = () => ows2.send(JSON.stringify({ t: 'join', name: 'Cu' }));
555	    ows2.onmessage = (e) => { const m = JSON.parse(e.data); oldMsgs.push(m); if (m.t === 'joined' && !oldTimer) oldTimer = setInterval(() => ows2.send(JSON.stringify({ t: 'pos', x: 300, y: 120, z: 0, yaw: 0, bank: 0 })), 200); };
556	    const a = walkBot('DaoA', -230, 8, 17.4, 1), b = walkBot('DaoB', -226, 8, 17.4, 2);
557	    await sleep(3000);
558	    const lob = oldMsgs.filter((m) => m.t === 'lobby'), pos = oldMsgs.filter((m) => m.t === 'pos'), jn = oldMsgs.find((m) => m.t === 'joined');
559	    const lastLob = lob.at(-1) || { flyers: [] };
560	    const okLob = lob.length >= 2 && lob.every((m) => Array.isArray(m.flyers) && m.flyers.every((f) => typeof f.slot === 'number' && typeof f.name === 'string' && f.name !== 'DaoA' && f.name !== 'DaoB'));
561	    const okPos = pos.length >= 3 && pos.every((m) => Array.isArray(m.f) && m.f.every((r) => Array.isArray(r) && r.length >= 6 && r[2] >= 7));   // f chỉ có người bay (y ≥ sàn bay 7 m); người đi dạo ở trường w
562	    const sawW = pos.some((m) => Array.isArray(m.w) && m.w.length > 0);
563	    check(`6d khách cũ: ${lob.length} lobby, flyers cuối ${JSON.stringify(lastLob.flyers)} không có người đi dạo; ${pos.length} gói pos đều có f kiểu cũ, f không có người đi dạo (w riêng: ${sawW}); joined ${JSON.stringify(jn)}`,
564	      okLob && okPos && sawW && jn && jn.slot === 0 && !('kind' in jn) && lastLob.flyers.length === 1 && lastLob.flyers[0].name === 'Cu');
565	    clearInterval(oldTimer); try { ows2.close(); } catch { /* bỏ qua */ }
566	    dropW(a); dropW(b);
567	    await sleep(2000);
568	  }
569	
570	  // 6b — trang đi dạo qua màn chọn: sảnh "Còn 5 trên 5 chỗ đi dạo", vào đi; bot bay hiện thành dù, bot đi dạo thứ hai hiện thành người chạy
571	  const GY = {};   // cao độ đứng thật tại các chỗ đặt bot (đọc từ bản đồ đi dạo của trang này)
572	  {
573	    const S = await openApp(browser, URLC + NOIDLE);
